if (typeof THREE === 'undefined') return;

if (!gdjs.__animatedPBR3D) {
    gdjs.__animatedPBR3D = (function() {
        const clamp = (val, min, max) => Math.max(min, Math.min(max, val));
        const isMesh = (node) => node && node.isMesh === true && node.material;

        const getRootObject3D = (object) => {
            if (!object) return null;
            if (typeof object.get3DRendererObject === 'function') {
                try {
                    const obj = object.get3DRendererObject();
                    if (obj) return obj;
                } catch(e) {}
            }
            return null;
        };

        const getBehaviorState = (behavior) => {
            if (!behavior.__animatedPBR3DState) {
                behavior.__animatedPBR3DState = {
                    state: 'Uninitialized',
                    error: '',
                    retryCount: 0,
                    meshesCount: 0,
                    materialsCount: 0,
                    targetMaterials: [],
                    originalMaterials: new Map(),
                    ownedMaterials: new Set(),
                    ownedTextures: new Map(), // slotName -> THREE.Texture
                    videoElement: null,
                    videoTexture: null,

                    // UV Animation runtime state
                    uvOffset: { x: 0, y: 0 },
                    uvRotation: 0,
                    isScrolling: false,
                    scrollSpeedX: 0,
                    scrollSpeedY: 0,
                    scrollRotSpeed: 0,

                    // Flipbook runtime state
                    flipbook: {
                        enabled: false,
                        isPlaying: true,
                        columns: 1,
                        rows: 1,
                        fps: 12,
                        loop: true,
                        totalFrames: 1,
                        currentFrame: 0,
                        timer: 0,
                        isFinished: false
                    },

                    lastAppliedSignature: null
                };
            }
            return behavior.__animatedPBR3DState;
        };

        const getBoolean = (behavior, name, def) => {
            const g = behavior['_get' + name];
            if (typeof g !== 'function') return def;
            const v = g.call(behavior);
            return v === true || v === 'true' || v === 1 || v === '1';
        };

        const getNumber = (behavior, name, def) => {
            const g = behavior['_get' + name];
            if (typeof g !== 'function') return def;
            const v = Number(g.call(behavior));
            return Number.isFinite(v) ? v : def;
        };

        const getString = (behavior, name, def) => {
            const g = behavior['_get' + name];
            return typeof g === 'function' ? String(g.call(behavior)) : def;
        };

        const parseColor = (colorString) => {
            const color = new THREE.Color();
            if (!colorString) return color.setRGB(1, 1, 1);
            if (colorString.indexOf(';') === -1) {
                try { color.set(colorString); return color; } catch(e) { return color.setRGB(1, 1, 1); }
            }
            const parts = colorString.split(';');
            const r = clamp(Number(parts[0]) || 0, 0, 255) / 255;
            const g = clamp(Number(parts[1]) || 0, 0, 255) / 255;
            const b = clamp(Number(parts[2]) || 0, 0, 255) / 255;
            color.setRGB(r, g, b, THREE.SRGBColorSpace);
            return color;
        };

        const collectMeshRecords = (root, includeChildren) => {
            const records = [];
            if (isMesh(root)) records.push(root);
            if (includeChildren) {
                root.traverse((child) => {
                    if (child !== root && isMesh(child)) records.push(child);
                });
            }
            return records;
        };

        const resolveTargets = (meshes, behavior) => {
            const targetMode = getString(behavior, 'TargetMode', 'All materials');
            const targetMatIndex = getNumber(behavior, 'MaterialIndex', 0);
            const targetMatName = getString(behavior, 'MaterialName', '');
            const targetMeshName = getString(behavior, 'MeshName', '');
            const results = [];
            let firstFound = false;

            for (const mesh of meshes) {
                if (targetMode === 'Mesh name' && mesh.name !== targetMeshName) continue;
                const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
                for (let i = 0; i < mats.length; i++) {
                    const mat = mats[i];
                    if (!mat) continue;
                    let match = false;
                    if (targetMode === 'All materials' || targetMode === 'Mesh name') match = true;
                    else if (targetMode === 'First material' && !firstFound) { match = true; firstFound = true; }
                    else if (targetMode === 'Material index' && i === targetMatIndex) match = true;
                    else if (targetMode === 'Material name' && mat.name === targetMatName) match = true;

                    if (match) {
                        results.push({ mesh, material: mat, index: i });
                        if (targetMode === 'First material') return results;
                    }
                }
            }
            return results;
        };

        const loadTextureFromResource = (game, resourceName, filterMode, state, slotKey) => {
            if (!resourceName || typeof resourceName !== 'string' || resourceName.trim() === '') {
                return null;
            }
            const resName = resourceName.trim();
            const imageManager = game.getImageManager();
            if (!imageManager) return null;

            // Check if we already have a loaded texture for this slot and resource
            const cacheKey = slotKey + ':' + resName + ':' + filterMode;
            if (state.ownedTextures.has(cacheKey)) {
                return state.ownedTextures.get(cacheKey);
            }

            let texture = null;

            // Try getting PIXI texture source
            try {
                const pixiTexture = imageManager.getPIXITexture(resName);
                let sourceElement = null;
                if (pixiTexture) {
                    if (pixiTexture.baseTexture && pixiTexture.baseTexture.resource && pixiTexture.baseTexture.resource.source) {
                        sourceElement = pixiTexture.baseTexture.resource.source;
                    } else if (pixiTexture.source && (pixiTexture.source.resource || pixiTexture.source)) {
                        sourceElement = pixiTexture.source.resource || pixiTexture.source;
                    }
                }

                if (sourceElement && (sourceElement instanceof HTMLImageElement || sourceElement instanceof HTMLCanvasElement || sourceElement instanceof ImageBitmap)) {
                    texture = new THREE.CanvasTexture ? new THREE.CanvasTexture(sourceElement) : new THREE.Texture(sourceElement);
                    texture.needsUpdate = true;
                }
            } catch(e) {}

            // Fallback: TextureLoader with resource URL
            if (!texture) {
                try {
                    let fileUrl = '';
                    if (typeof imageManager.getResource === 'function') {
                        const res = imageManager.getResource(resName);
                        if (res && res.file) fileUrl = res.file;
                    }
                    if (!fileUrl && typeof imageManager._getURL === 'function') {
                        fileUrl = imageManager._getURL(resName);
                    }
                    if (!fileUrl) fileUrl = resName;

                    const loader = new THREE.TextureLoader();
                    texture = loader.load(fileUrl);
                } catch(e) {}
            }

            if (texture) {
                texture.wrapS = THREE.RepeatWrapping;
                texture.wrapT = THREE.RepeatWrapping;
                if (filterMode === 'Nearest') {
                    texture.magFilter = THREE.NearestFilter;
                    texture.minFilter = THREE.NearestFilter;
                } else if (filterMode === 'Linear') {
                    texture.magFilter = THREE.LinearFilter;
                    texture.minFilter = THREE.LinearMipmapLinearFilter;
                }
                texture.needsUpdate = true;
                state.ownedTextures.set(cacheKey, texture);
            }

            return texture;
        };

        const applyTextureTransform = (texture, tilingX, tilingY, offsetX, offsetY, rotation, centerX, centerY) => {
            if (!texture) return;
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            texture.repeat.set(tilingX, tilingY);
            texture.offset.set(offsetX, offsetY);
            texture.rotation = (rotation || 0) * (Math.PI / 180);
            texture.center.set(centerX !== undefined ? centerX : 0.5, centerY !== undefined ? centerY : 0.5);
            texture.needsUpdate = true;
        };

        const updateAllMaterialTextures = (state, behavior, game) => {
            const filterMode = getString(behavior, 'TextureFiltering', 'Keep Original');
            const tilingX = getNumber(behavior, 'TilingX', 1);
            const tilingY = getNumber(behavior, 'TilingY', 1);
            const offsetX = getNumber(behavior, 'OffsetX', 0) + state.uvOffset.x;
            const offsetY = getNumber(behavior, 'OffsetY', 0) + state.uvOffset.y;
            const rotAngle = getNumber(behavior, 'RotationAngle', 0) + state.uvRotation;
            const centerX = getNumber(behavior, 'RotationCenterX', 0.5);
            const centerY = getNumber(behavior, 'RotationCenterY', 0.5);

            // Handle Flipbook calculations
            let finalTilingX = tilingX;
            let finalTilingY = tilingY;
            let finalOffsetX = offsetX;
            let finalOffsetY = offsetY;

            if (state.flipbook.enabled) {
                const cols = Math.max(1, state.flipbook.columns);
                const rows = Math.max(1, state.flipbook.rows);
                const frameW = 1.0 / cols;
                const frameH = 1.0 / rows;
                const curFrame = state.flipbook.currentFrame;
                const colIdx = curFrame % cols;
                const rowIdx = Math.floor(curFrame / cols);

                finalTilingX = frameW * tilingX;
                finalTilingY = frameH * tilingY;
                finalOffsetX = (colIdx * frameW) + offsetX;
                finalOffsetY = (1.0 - frameH - (rowIdx * frameH)) + offsetY;
            }

            const albedoRes = getString(behavior, 'AlbedoMap', '');
            const normalRes = getString(behavior, 'NormalMap', '');
            const roughRes = getString(behavior, 'RoughnessMap', '');
            const metalRes = getString(behavior, 'MetalnessMap', '');
            const aoRes = getString(behavior, 'AOMap', '');
            const emissiveRes = getString(behavior, 'EmissiveMap', '');

            const albedoTex = state.videoTexture ? state.videoTexture : loadTextureFromResource(game, albedoRes, filterMode, state, 'albedo');
            const normalTex = loadTextureFromResource(game, normalRes, filterMode, state, 'normal');
            const roughTex = loadTextureFromResource(game, roughRes, filterMode, state, 'roughness');
            const metalTex = loadTextureFromResource(game, metalRes, filterMode, state, 'metalness');
            const aoTex = loadTextureFromResource(game, aoRes, filterMode, state, 'ao');
            const emissiveTex = loadTextureFromResource(game, emissiveRes, filterMode, state, 'emissive');

            const allTextures = [albedoTex, normalTex, roughTex, metalTex, aoTex, emissiveTex].filter(t => !!t);
            for (const tex of allTextures) {
                applyTextureTransform(tex, finalTilingX, finalTilingY, finalOffsetX, finalOffsetY, rotAngle, centerX, centerY);
            }

            for (const mat of state.targetMaterials) {
                if (!mat) continue;
                if (albedoTex) mat.map = albedoTex;
                if (normalTex) {
                    mat.normalMap = normalTex;
                    const nScale = getNumber(behavior, 'NormalScale', 1.0);
                    if (mat.normalScale) mat.normalScale.set(nScale, nScale);
                }
                if (roughTex) mat.roughnessMap = roughTex;
                if (metalTex) mat.metalnessMap = metalTex;
                if (aoTex) {
                    mat.aoMap = aoTex;
                    mat.aoMapIntensity = getNumber(behavior, 'AOIntensity', 1.0);
                }
                if (emissiveTex) mat.emissiveMap = emissiveTex;

                mat.needsUpdate = true;
            }
        };

        const applyMaterialSettings = (mat, behavior) => {
            const useBaseColor = getBoolean(behavior, 'UseBaseColor', false);
            if (useBaseColor && mat.color) {
                mat.color.copy(parseColor(getString(behavior, 'BaseColor', '255;255;255')));
            }

            if (mat.isMeshStandardMaterial || mat.isMeshPhysicalMaterial) {
                mat.metalness = clamp(getNumber(behavior, 'Metalness', 0.0), 0, 1);
                mat.roughness = clamp(getNumber(behavior, 'Roughness', 0.5), 0, 1);

                const emissiveColor = parseColor(getString(behavior, 'EmissiveColor', '0;0;0'));
                if (mat.emissive) mat.emissive.copy(emissiveColor);
                if (mat.emissiveIntensity !== undefined) {
                    mat.emissiveIntensity = Math.max(0, getNumber(behavior, 'EmissiveStrength', 1.0));
                }
            }

            const alphaMode = getString(behavior, 'AlphaMode', 'Opaque');
            const alpha = clamp(getNumber(behavior, 'Alpha', 1.0), 0, 1);
            const alphaCutoff = clamp(getNumber(behavior, 'AlphaCutoff', 0.1), 0, 1);
            const depthWrite = getBoolean(behavior, 'DepthWrite', true);

            mat.depthWrite = depthWrite;
            mat.blending = THREE.NormalBlending;

            if (alphaMode === 'Opaque') {
                mat.transparent = false;
                mat.opacity = 1.0;
                mat.alphaTest = 0;
            } else if (alphaMode === 'Blend') {
                mat.transparent = true;
                mat.opacity = alpha;
                mat.alphaTest = 0;
            } else if (alphaMode === 'Cutout') {
                mat.transparent = false;
                mat.opacity = 1.0;
                mat.alphaTest = alphaCutoff;
            } else if (alphaMode === 'Additive') {
                mat.transparent = true;
                mat.opacity = alpha;
                mat.alphaTest = 0;
                mat.blending = THREE.AdditiveBlending;
            } else if (alphaMode === 'Multiply') {
                mat.transparent = true;
                mat.opacity = alpha;
                mat.alphaTest = 0;
                mat.blending = THREE.MultiplyBlending;
            }

            const sideMode = getString(behavior, 'MaterialSide', 'Front');
            mat.side = sideMode === 'Back' ? THREE.BackSide : sideMode === 'Double' ? THREE.DoubleSide : THREE.FrontSide;
            if (mat.wireframe !== undefined) mat.wireframe = getBoolean(behavior, 'Wireframe', false);

            mat.needsUpdate = true;
        };

        const computeSettingsSignature = (behavior) => {
            return [
                getString(behavior, 'TargetMode', ''),
                getNumber(behavior, 'MaterialIndex', 0),
                getString(behavior, 'MaterialName', ''),
                getString(behavior, 'MeshName', ''),
                getString(behavior, 'AlbedoMap', ''),
                getString(behavior, 'BaseColor', ''),
                getBoolean(behavior, 'UseBaseColor', false),
                getString(behavior, 'NormalMap', ''),
                getNumber(behavior, 'NormalScale', 1),
                getString(behavior, 'RoughnessMap', ''),
                getNumber(behavior, 'Roughness', 0.5),
                getString(behavior, 'MetalnessMap', ''),
                getNumber(behavior, 'Metalness', 0),
                getString(behavior, 'AOMap', ''),
                getNumber(behavior, 'AOIntensity', 1),
                getString(behavior, 'EmissiveMap', ''),
                getString(behavior, 'EmissiveColor', ''),
                getNumber(behavior, 'EmissiveStrength', 1),
                getString(behavior, 'TextureFiltering', ''),
                getNumber(behavior, 'TilingX', 1),
                getNumber(behavior, 'TilingY', 1),
                getNumber(behavior, 'OffsetX', 0),
                getNumber(behavior, 'OffsetY', 0),
                getNumber(behavior, 'RotationAngle', 0),
                getString(behavior, 'AlphaMode', ''),
                getNumber(behavior, 'Alpha', 1),
                getNumber(behavior, 'AlphaCutoff', 0.1),
                getBoolean(behavior, 'DepthWrite', true),
                getString(behavior, 'MaterialSide', ''),
                getBoolean(behavior, 'Wireframe', false)
            ].join('|');
        };

        const applyToBehavior = (behavior, object, game) => {
            const state = getBehaviorState(behavior);
            const root = getRootObject3D(object);
            if (!root) {
                if (state.state === 'Uninitialized' || state.state === 'WaitingForRenderer') {
                    state.state = 'WaitingForRenderer';
                    state.retryCount++;
                    if (state.retryCount > 180) {
                        state.error = '3D Renderer object not available.';
                        state.state = 'Failed';
                    }
                }
                return;
            }

            try {
                const includeChildren = getBoolean(behavior, 'IncludeChildren', true);
                const allMeshes = collectMeshRecords(root, includeChildren);
                if (allMeshes.length === 0) {
                    state.error = 'No compatible meshes found.';
                    state.state = 'Failed';
                    return;
                }

                const targets = resolveTargets(allMeshes, behavior);
                state.meshesCount = new Set(targets.map(t => t.mesh)).size;
                state.materialsCount = targets.length;

                if (targets.length === 0) {
                    state.error = 'No matching materials found.';
                    state.state = 'Failed';
                    return;
                }

                const cloneMaterials = getBoolean(behavior, 'CloneMaterials', true);
                const appliedMaterials = [];

                for (const target of targets) {
                    const mesh = target.mesh;
                    if (!state.originalMaterials.has(mesh.uuid)) {
                        state.originalMaterials.set(mesh.uuid, Array.isArray(mesh.material) ? mesh.material.slice() : [mesh.material]);
                    }

                    const origArray = state.originalMaterials.get(mesh.uuid);
                    const baseMat = origArray[target.index] || origArray[0];

                    let newMat;
                    if (cloneMaterials) {
                        newMat = (baseMat && baseMat.isMeshStandardMaterial) ? baseMat.clone() : new THREE.MeshStandardMaterial();
                        if (baseMat) {
                            // Copy standard properties
                            newMat.name = baseMat.name;
                            if (baseMat.color) newMat.color.copy(baseMat.color);
                            if (baseMat.map) newMat.map = baseMat.map;
                            newMat.roughness = baseMat.roughness !== undefined ? baseMat.roughness : 0.5;
                            newMat.metalness = baseMat.metalness !== undefined ? baseMat.metalness : 0.0;
                        }
                        state.ownedMaterials.add(newMat);
                    } else {
                        newMat = baseMat;
                    }

                    applyMaterialSettings(newMat, behavior);

                    if (Array.isArray(mesh.material)) {
                        mesh.material[target.index] = newMat;
                    } else {
                        mesh.material = newMat;
                    }

                    mesh.castShadow = getBoolean(behavior, 'CastShadow', true);
                    mesh.receiveShadow = getBoolean(behavior, 'ReceiveShadow', true);

                    appliedMaterials.push(newMat);
                }

                state.targetMaterials = appliedMaterials;

                // Sync animation properties from inspector
                state.isScrolling = getBoolean(behavior, 'EnableScroll', false);
                state.scrollSpeedX = getNumber(behavior, 'ScrollSpeedX', 0.0);
                state.scrollSpeedY = getNumber(behavior, 'ScrollSpeedY', 0.0);
                state.scrollRotSpeed = getNumber(behavior, 'ScrollRotationSpeed', 0.0);

                state.flipbook.enabled = getBoolean(behavior, 'EnableFlipbook', false);
                state.flipbook.columns = Math.max(1, getNumber(behavior, 'FlipbookColumns', 1));
                state.flipbook.rows = Math.max(1, getNumber(behavior, 'FlipbookRows', 1));
                state.flipbook.fps = Math.max(0.1, getNumber(behavior, 'FlipbookFPS', 12));
                state.flipbook.loop = getBoolean(behavior, 'FlipbookLoop', true);
                const totalF = getNumber(behavior, 'FlipbookTotalFrames', 0);
                state.flipbook.totalFrames = totalF > 0 ? totalF : (state.flipbook.columns * state.flipbook.rows);

                updateAllMaterialTextures(state, behavior, game);

                state.state = 'Ready';
                state.error = '';
                state.lastAppliedSignature = computeSettingsSignature(behavior);
            } catch(e) {
                state.error = 'Material setup error: ' + e.message;
                state.state = 'Failed';
                console.error('[AnimatedPBR3D]', e);
            }
        };

        const tick = (behavior, object, runtimeScene) => {
            const state = getBehaviorState(behavior);
            if (state.state === 'Uninitialized' || state.state === 'WaitingForRenderer') {
                applyToBehavior(behavior, object, runtimeScene.getGame());
                return;
            }
            if (state.state !== 'Ready') return;

            const dt = runtimeScene.getTimeManager().getElapsedTime() / 1000.0;
            let needsTexUpdate = false;

            // 1. Advance UV Scrolling
            if (state.isScrolling && (state.scrollSpeedX !== 0 || state.scrollSpeedY !== 0 || state.scrollRotSpeed !== 0)) {
                state.uvOffset.x += state.scrollSpeedX * dt;
                state.uvOffset.y += state.scrollSpeedY * dt;
                state.uvRotation += state.scrollRotSpeed * dt;
                needsTexUpdate = true;
            }

            // 2. Advance Flipbook Spritesheet
            if (state.flipbook.enabled && state.flipbook.isPlaying && !state.flipbook.isFinished) {
                state.flipbook.timer += dt;
                const frameDuration = 1.0 / state.flipbook.fps;
                if (state.flipbook.timer >= frameDuration) {
                    const framesToAdvance = Math.floor(state.flipbook.timer / frameDuration);
                    state.flipbook.timer -= framesToAdvance * frameDuration;
                    state.flipbook.currentFrame += framesToAdvance;

                    if (state.flipbook.currentFrame >= state.flipbook.totalFrames) {
                        if (state.flipbook.loop) {
                            state.flipbook.currentFrame = state.flipbook.currentFrame % state.flipbook.totalFrames;
                        } else {
                            state.flipbook.currentFrame = state.flipbook.totalFrames - 1;
                            state.flipbook.isFinished = true;
                            state.flipbook.isPlaying = false;
                        }
                    }
                    needsTexUpdate = true;
                }
            }

            // 3. Update Video Texture if playing
            if (state.videoTexture && state.videoElement && !state.videoElement.paused) {
                state.videoTexture.needsUpdate = true;
            }

            if (needsTexUpdate) {
                updateAllMaterialTextures(state, behavior, runtimeScene.getGame());
            }
        };

        const restoreOriginalMaterials = (state, allMeshes) => {
            for (const mesh of allMeshes) {
                if (state.originalMaterials.has(mesh.uuid)) {
                    const orig = state.originalMaterials.get(mesh.uuid);
                    mesh.material = Array.isArray(mesh.material) ? orig.slice() : orig[0];
                }
            }
            for (const mat of state.ownedMaterials) {
                try { mat.dispose(); } catch(e) {}
            }
            for (const tex of state.ownedTextures.values()) {
                try { tex.dispose(); } catch(e) {}
            }
            if (state.videoElement) {
                try {
                    state.videoElement.pause();
                    state.videoElement.src = '';
                    state.videoElement.load();
                } catch(e) {}
            }
            state.ownedMaterials.clear();
            state.ownedTextures.clear();
            state.originalMaterials.clear();
            state.targetMaterials = [];
            state.state = 'Uninitialized';
        };

        return {
            getBehaviorState,
            getRootObject3D,
            collectMeshRecords,
            applyToBehavior,
            updateAllMaterialTextures,
            tick,
            restoreOriginalMaterials,
            loadTextureFromResource
        };
    })();
}


gdjs.__animatedPBR3D.tick(behavior, object, runtimeScene);

if (typeof THREE === 'undefined') return;
const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
const root = gdjs.__animatedPBR3D.getRootObject3D(object);
if (root) {
    const allMeshes = gdjs.__animatedPBR3D.collectMeshRecords(root, true);
    gdjs.__animatedPBR3D.restoreOriginalMaterials(state, allMeshes);
} else {
    gdjs.__animatedPBR3D.restoreOriginalMaterials(state, []);
}

const res = eventsFunctionContext.getArgument("ResourceName");
behavior._setAlbedoMap(res);
const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
state.videoTexture = null;
gdjs.__animatedPBR3D.updateAllMaterialTextures(state, behavior, runtimeScene.getGame());

const r = Math.max(0, Math.min(255, eventsFunctionContext.getArgument("Red")));
const g = Math.max(0, Math.min(255, eventsFunctionContext.getArgument("Green")));
const b = Math.max(0, Math.min(255, eventsFunctionContext.getArgument("Blue")));
behavior._setEmissiveMap(eventsFunctionContext.getArgument("ResourceName"));
behavior._setEmissiveColor(r + ";" + g + ";" + b);
behavior._setEmissiveStrength(eventsFunctionContext.getArgument("Strength"));
const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
gdjs.__animatedPBR3D.applyToBehavior(behavior, object, runtimeScene.getGame());

const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
state.scrollSpeedX = eventsFunctionContext.getArgument("SpeedX");
state.scrollSpeedY = eventsFunctionContext.getArgument("SpeedY");
state.scrollRotSpeed = eventsFunctionContext.getArgument("RotSpeed");
state.isScrolling = true;

const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
state.flipbook.enabled = true;
state.flipbook.columns = Math.max(1, eventsFunctionContext.getArgument("Columns"));
state.flipbook.rows = Math.max(1, eventsFunctionContext.getArgument("Rows"));
state.flipbook.fps = Math.max(0.1, eventsFunctionContext.getArgument("FPS"));
state.flipbook.loop = eventsFunctionContext.getArgument("Loop");
state.flipbook.totalFrames = state.flipbook.columns * state.flipbook.rows;
state.flipbook.isPlaying = true;
state.flipbook.isFinished = false;
gdjs.__animatedPBR3D.updateAllMaterialTextures(state, behavior, runtimeScene.getGame());

const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
const frame = Math.max(0, Math.floor(eventsFunctionContext.getArgument("FrameIndex")));
state.flipbook.currentFrame = frame % state.flipbook.totalFrames;
state.flipbook.timer = 0;
gdjs.__animatedPBR3D.updateAllMaterialTextures(state, behavior, runtimeScene.getGame());

const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
state.flipbook.enabled = true;
state.flipbook.isPlaying = true;
state.flipbook.isFinished = false;

const state = gdjs.__animatedPBR3D.getBehaviorState(behavior);
const videoUrl = eventsFunctionContext.getArgument("VideoURL");
const loop = eventsFunctionContext.getArgument("Loop");
const muted = eventsFunctionContext.getArgument("Muted");

if (!state.videoElement) {
    state.videoElement = document.createElement('video');
    state.videoElement.crossOrigin = 'anonymous';
    state.videoElement.playsInline = true;
}

state.videoElement.src = videoUrl;
state.videoElement.loop = loop;
state.videoElement.muted = muted;
state.videoElement.play().catch(err => console.warn('[AnimatedPBR3D] Video autoplay prevented:', err));

if (!state.videoTexture) {
    state.videoTexture = new THREE.VideoTexture(state.videoElement);
    state.videoTexture.wrapS = THREE.RepeatWrapping;
    state.videoTexture.wrapT = THREE.RepeatWrapping;
}

gdjs.__animatedPBR3D.updateAllMaterialTextures(state, behavior, runtimeScene.getGame());
